                if ($("input[name=" + attr + "]").length > 0 && $("input[name=" + attr + "]").is(":visible")) {
                    if ($($("input[name=" + attr + "]")[0]).closest('.form-group').hasClass('required') && (value == "" || value == undefined)) {
                        return i18next.t('candidate_validation_field_is_required');
                    }
                    if(value!='') {
                        var min = parseInt($("input[name=" + attr + "]").attr('minlength'), 10);
                        if (isNaN(min) || min < 1) { min = 10; }
                        var max = parseInt($("input[name=" + attr + "]").attr('maxlength'), 10);
                        if (isNaN(max) || max < min) { max = 15; }
                        var pattern = new RegExp('^\\d{' + min + ',' + max + '}$');
